using System;
using System.Collections.Generic;
using System.Data;

namespace TACT.Server.DataAccess
{

/// <summary>
    /// High-throughput Dapper connection factory & audit log writer.
    /// Replaces legacy OLE DB connection pool that suffered from handle leaks under burst load.
    /// Runs on the Mutation Lane (MaxDOP = 1) defined in ADR-001.
    /// </summary>
    public sealed class AuditLogBatchWriter
    {
        private const int MAX_BATCH_SIZE = 250;                  // Rule ID: BR-DB-501
        private const int COMMAND_TIMEOUT_SECONDS = 5;           // Rule ID: BR-DB-502
        private const string PROVIDER_ENGINE = "Dapper_SqlConnection_ExplicitFactory";

/// <summary>
        /// Business Rule BR-DB-501 & BR-DB-502:
        /// All command execution audit logs must be flushed in deterministic batches of <= 250 records
        /// with a strict 5-second command timeout over an explicit Dapper SqlConnection factory,
        /// completely bypassing the deprecated OleDbConnection pool.
        /// </summary>
        public int ValidateBatchFlushPolicy(int pendingRecordCount, string connectionProvider)
        {
            if (string.Equals(connectionProvider, "Legacy_OleDb_Pool", StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException("BR-DB-501 Violation: Legacy_OleDb_Pool is prohibited due to connection leak risk.");
            }

            if (pendingRecordCount <= 0)
            {
                return 0;
            }

            return Math.Min(pendingRecordCount, MAX_BATCH_SIZE);
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;

namespace TACT.Server.Policy
{

/// <summary>
    /// Legacy Network Device Command Policy Engine.
    /// Enforces model-scoped whitelists and blocks destructive CLI commands before reaching SSH/Telnet sessions.
    /// </summary>
    public sealed class CommandPolicyEngine
    {
        private readonly ConcurrentDictionary<string, HashSet<string>> _modelExactWhitelist =
            new ConcurrentDictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);

        private readonly ConcurrentDictionary<string, List<string>> _modelPrefixRules =
            new ConcurrentDictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);

        // Hard-coded emergency blocklist across all network equipment models (Rule ID: BR-POL-001)
        private static readonly string[] GlobalBlockedCommands = new[]
        {
            "reload",
            "write erase",
            "delete flash:",
            "format flash:",
            "request system zeroize",
            "shutdown interface core-uplink"
        };

/// <summary>
        /// Business Rule BR-POL-002:
        /// Privileged configuration mode ("configure terminal" or "system-view") requires:
        /// 1. Operator role level >= 3 (NOC Senior or Principal)
        /// 2. Active bastion session mode == Mode3_KAM_SSH
        /// 3. Explicit device-model whitelist registration
        /// </summary>
        public PolicyDecision EvaluateCommand(string deviceModel, string commandText, int operatorRoleLevel, string bastionMode)
        {
            if (string.IsNullOrWhiteSpace(commandText))
            {
                return PolicyDecision.Deny("BR-POL-000", "Empty command payload is not permitted.");
            }

            string normalized = commandText.Trim();

            foreach (var blocked in GlobalBlockedCommands)
            {
                if (normalized.StartsWith(blocked, StringComparison.OrdinalIgnoreCase))
                {
                    return PolicyDecision.Deny("BR-POL-001", $"Command '{normalized}' is globally prohibited on production equipment.");
                }
            }

            bool isConfigEntry = normalized.Equals("configure terminal", StringComparison.OrdinalIgnoreCase)
                              || normalized.Equals("conf t", StringComparison.OrdinalIgnoreCase)
                              || normalized.Equals("system-view", StringComparison.OrdinalIgnoreCase);

            if (isConfigEntry)
            {
                if (operatorRoleLevel < 3)
                {
                    return PolicyDecision.Deny("BR-POL-002A", "Privileged config mode requires OperatorRoleLevel >= 3.");
                }

                if (!string.Equals(bastionMode, "Mode3_KAM_SSH", StringComparison.OrdinalIgnoreCase))
                {
                    return PolicyDecision.Deny("BR-POL-002B", "Privileged config mode is only allowed over Mode3_KAM_SSH bastion topology.");
                }
            }

            if (_modelExactWhitelist.TryGetValue(deviceModel, out var exactSet) && exactSet.Contains(normalized))
            {
                return PolicyDecision.Allow("BR-POL-003", "Matched exact model-scoped whitelist.");
            }

            if (_modelPrefixRules.TryGetValue(deviceModel, out var prefixes))
            {
                foreach (var prefix in prefixes)
                {
                    if (normalized.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                    {
                        return PolicyDecision.Allow("BR-POL-004", $"Matched prefix rule '{prefix}' for model {deviceModel}.");
                    }
                }
            }

            return PolicyDecision.Deny("BR-POL-999", $"Command '{normalized}' is not whitelisted for device model '{deviceModel}'.");
        }
    }

public sealed class PolicyDecision
    {
        public bool IsAllowed { get; }
        public string RuleId { get; }
        public string Reason { get; }

        private PolicyDecision(bool isAllowed, string ruleId, string reason)
        {
            IsAllowed = isAllowed;
            RuleId = ruleId;
            Reason = reason;
        }

public static PolicyDecision Allow(string ruleId, string reason) => new PolicyDecision(true, ruleId, reason);
        public static PolicyDecision Deny(string ruleId, string reason) => new PolicyDecision(false, ruleId, reason);
    }
}

using System;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

namespace TACT.Server.Transport
{

/// <summary>
    /// Manages Mode 3 KAM SSH Bastion dual-topology routing and legacy Telnet fallback sessions.
    /// Cooperates with CommandPolicyEngine before dispatching privileged frames.
    /// See also: ADR-001, ADR-002.
    /// </summary>
    public sealed class LegacyTelnetSessionManager
    {
        private const int DEFAULT_IDLE_TIMEOUT_SEC = 180;
        private const int BASTION_KEEPALIVE_INTERVAL_MS = 15000; // 15s heartbeat (Rule ID: BR-NET-401)
        private const int MAX_RECONNECT_ATTEMPTS = 3;            // Rule ID: BR-NET-402

/// <summary>
        /// Distractor method: evaluates legacy local debug console permissions (NOT production equipment).
        /// Local debug console allows role level >= 1 on Loopback_Debug mode (Rule ID: BR-DBG-009).
        /// </summary>
        public bool EvaluateLocalDebugConsole(int operatorRoleLevel, string mode)
        {
            return operatorRoleLevel >= 1 && string.Equals(mode, "Loopback_Debug", StringComparison.OrdinalIgnoreCase);
        }

/// <summary>
        /// Business Rule BR-NET-401 & BR-NET-402:
        /// Resolves dual-bastion routing path during zero-downtime migration.
        /// - Primary path uses Mode3_KAM_SSH with a 15,000ms (15s) KeepAlive heartbeat interval.
        /// - If primary bastion handshake fails, retries up to 3 times (MAX_RECONNECT_ATTEMPTS = 3)
        ///   with exponential backoff before failing over to Legacy_Bastion_V2.
        /// - Invokes CommandPolicyEngine.EvaluateCommand prior to opening configuration channels.
        /// </summary>
        public BastionRouteResult ResolveBastionTopology(string deviceGroupCode, int failedAttempts, bool requireConfigChannel)
        {
            if (failedAttempts >= MAX_RECONNECT_ATTEMPTS)
            {
                return new BastionRouteResult(
                    "Legacy_Bastion_V2",
                    BASTION_KEEPALIVE_INTERVAL_MS,
                    "BR-NET-402",
                    "Primary KAM SSH exceeded 3 reconnect attempts; failed over to Legacy_Bastion_V2."
                );
            }

            string selectedTopology = deviceGroupCode.StartsWith("CORE-", StringComparison.OrdinalIgnoreCase)
                ? "Mode3_KAM_SSH"
                : "Dual_Coexistence_SSH";

            return new BastionRouteResult(
                selectedTopology,
                BASTION_KEEPALIVE_INTERVAL_MS,
                "BR-NET-401",
                $"Routed via {selectedTopology} with {BASTION_KEEPALIVE_INTERVAL_MS}ms KeepAlive heartbeat."
            );
        }
    }

public sealed class BastionRouteResult
    {
        public string Topology { get; }
        public int KeepAliveIntervalMs { get; }
        public string RuleId { get; }
        public string AuditNote { get; }

        public BastionRouteResult(string topology, int keepAliveIntervalMs, string ruleId, string auditNote)
        {
            Topology = topology;
            KeepAliveIntervalMs = keepAliveIntervalMs;
            RuleId = ruleId;
            AuditNote = auditNote;
        }
    }
}

package com.enterprise.wealth.robo;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;

/**
 * Legacy Robo-Advisor Portfolio Rebalancing & Risk Engine.
 * Extracted during Next-Gen Financial Risk Management Modernization.
 */
public class RoboAdvisorRebalanceService {

    private static final BigDecimal MAX_EQUITY_CAP_CONSERVATIVE = new BigDecimal("0.20");
    private static final BigDecimal MAX_EQUITY_CAP_BALANCED = new BigDecimal("0.50");
    private static final BigDecimal DRIFT_THRESHOLD_TRIGGER = new BigDecimal("0.035"); // 3.5% drift threshold (Rule ID: BR-FIN-101)
    private static final BigDecimal HIGH_VOLATILITY_VIX_CUTOFF = new BigDecimal("28.5"); // Rule ID: BR-FIN-102

/**
     * Business Rule BR-FIN-101 & BR-FIN-102:
     * Determines whether an automated discretionary pension portfolio requires rebalancing.
     * - Rebalancing triggers only if absolute asset-class drift >= 3.5% (0.035).
     * - If market volatility index (VIX) exceeds 28.5, equity buy orders are halted and shifted to sovereign bonds.
     */
    public RebalanceDecision evaluatePortfolioDrift(
            String riskProfile,
            BigDecimal currentEquityWeight,
            BigDecimal targetEquityWeight,
            BigDecimal currentVixIndex) {

        BigDecimal maxAllowedEquity = "CONSERVATIVE".equalsIgnoreCase(riskProfile)
                ? MAX_EQUITY_CAP_CONSERVATIVE
                : MAX_EQUITY_CAP_BALANCED;

        if (currentEquityWeight.compareTo(maxAllowedEquity) > 0) {
            return new RebalanceDecision(
                    true,
                    "BR-FIN-100",
                    "FORCE_DELEVERAGE_EQUITY",
                    currentEquityWeight.subtract(maxAllowedEquity).setScale(4, RoundingMode.HALF_UP)
            );
        }

        BigDecimal absoluteDrift = currentEquityWeight.subtract(targetEquityWeight).abs();
        if (absoluteDrift.compareTo(DRIFT_THRESHOLD_TRIGGER) < 0) {
            return new RebalanceDecision(false, "BR-FIN-101", "HOLD_WITHIN_DRIFT_BAND", absoluteDrift);
        }

        if (currentVixIndex.compareTo(HIGH_VOLATILITY_VIX_CUTOFF) > 0
                && currentEquityWeight.compareTo(targetEquityWeight) < 0) {
            return new RebalanceDecision(
                    false,
                    "BR-FIN-102",
                    "HALT_EQUITY_BUY_VIX_CIRCUIT_BREAKER",
                    absoluteDrift
            );
        }

        return new RebalanceDecision(true, "BR-FIN-103", "EXECUTE_STANDARD_REBALANCE", absoluteDrift);
    }

public static final class RebalanceDecision {
        private final boolean rebalanceRequired;
        private final String ruleId;
        private final String actionCode;
        private final BigDecimal metricValue;

        public RebalanceDecision(boolean rebalanceRequired, String ruleId, String actionCode, BigDecimal metricValue) {
            this.rebalanceRequired = rebalanceRequired;
            this.ruleId = ruleId;
            this.actionCode = actionCode;
            this.metricValue = metricValue;
        }

public boolean isRebalanceRequired() { return rebalanceRequired; }
        public String getRuleId() { return ruleId; }
        public String getActionCode() { return actionCode; }
        public BigDecimal getMetricValue() { return metricValue; }
    }
}
